const panel = t3template.addPanel({ title: 'Hot Spots', position: 'top' });
t3template.addControl({ id: 'hot', label: 'Self At Least (ms)', type: 'slider', min: 0, max: 200, step: 5, default: 0, panel, onChange(v, t) { t.instances.grid.set({ filters: v > 0 ? { 'self ms': '>=' + v } : {} }); t.refresh(); } });
t3template.addPreset('Self Icicle', { metric: 'self', view: 'icicle', zoom: [] });
t3template.addToolbarButton('Self Only', (t) => t.setValues({ metric: 'self' }, 'Self Only'), { shortcut: 'shift+s' });
